  // =====================================================================================================
  // Français : grammaire, conjugaison, vocabulaire, littérature
  // =====================================================================================================
  // conjugaison des verbes du 1er groupe (radical régulier)
  const V1 = [["chanter", "chant"], ["parler", "parl"], ["marcher", "march"], ["danser", "dans"], ["jouer", "jou"], ["aimer", "aim"], ["donner", "donn"], ["regarder", "regard"], ["travailler", "travaill"], ["écouter", "écout"], ["arriver", "arriv"], ["porter", "port"], ["cultiver", "cultiv"], ["préparer", "prépar"], ["raconter", "racont"]];
  const PRON = ["je", "tu", "il", "nous", "vous", "ils"], el = (p, v) => (p === "je" && /^[aeéèiouy]/.test(v) ? "j'" + v : p + " " + v);
  const T1 = { "présent": ["e", "es", "e", "ons", "ez", "ent"], "imparfait": ["ais", "ais", "ait", "ions", "iez", "aient"], "futur simple": ["erai", "eras", "era", "erons", "erez", "eront"], "passé simple": ["ai", "as", "a", "âmes", "âtes", "èrent"], "conditionnel présent": ["erais", "erais", "erait", "erions", "eriez", "eraient"], "subjonctif présent": ["e", "es", "e", "ions", "iez", "ent"] };
  const conj1 = (tps, filtre) => (r) => { const [inf, rad] = pick(r, V1), k = ri(r, 0, 5), t = pick(r, tps), ok = el(PRON[k], rad + T1[t][k]), sub = t === "subjonctif présent" ? "que " : "";
    const pool = Object.keys(T1).filter((x) => x !== t).map((x) => el(PRON[k], rad + T1[x][k])).filter((x) => x !== ok);
    return { q: `Conjugue « ${inf} » au ${t}, ${k + 1 > 3 ? k - 2 + "e personne du pluriel" : k + 1 + "e personne du singulier"} :`, ok: sub + ok, faux: autres(r, pool.map((x) => sub + x), sub + ok), e: `${t[0].toUpperCase() + t.slice(1)} des verbes en -er : ${T1[t].map((x, i) => (i === 0 && /^[aeéèiouy]/.test(rad) ? "j'" : PRON[i] + " ") + rad + x).join(", ")}.` }; };
  add("6e-francais", "Conjugaison : présent, imparfait, futur", conj1(["présent", "imparfait", "futur simple"]));
  add("5e-francais", "Conjugaison : passé composé, passé simple, futur", conj1(["passé simple", "futur simple"]));
  add("4e-francais", "Conjugaison : conditionnel et subjonctif", conj1(["conditionnel présent", "subjonctif présent"]));
